package com.example.boilerplatefree.model;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.EqualsAndHashCode;
import lombok.NoArgsConstructor;
import lombok.ToString;

import java.time.Instant;
import java.util.List;

@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
@ToString(exclude = "passwordHash")
@EqualsAndHashCode(of = "id")
public class User {

    private Long id;
    private String username;
    private String email;
    private String passwordHash;
    private List<String> roles;
    private Instant createdAt;

    public boolean isAdmin() {
        return roles != null && roles.contains("ADMIN");
    }
}

package com.example.boilerplatefree;

import com.example.boilerplatefree.model.User;
import lombok.extern.java.Log;

import java.time.Instant;
import java.util.List;

@Log
public class App {

    public static void main(String[] args) {
        User user = User.builder()
                .id(1L)
                .username("ada")
                .email("ada@example.com")
                .passwordHash("s3cr3t")
                .roles(List.of("ADMIN", "USER"))
                .createdAt(Instant.now())
                .build();

        log.info("Created user: " + user);

        user.setEmail("ada.lovelace@example.com");
        log.info("isAdmin=" + user.isAdmin() + ", email=" + user.getEmail());
    }
}

package com.example.boilerplatefree.model;

import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class UserTest {

    @Test
    void builderPopulatesGetters() {
        User user = User.builder()
                .id(1L)
                .username("ada")
                .roles(List.of("USER"))
                .build();

        assertEquals("ada", user.getUsername());
        assertTrue(user.getRoles().contains("USER"));
    }

    @Test
    void equalsUsesIdOnly() {
        User a = User.builder().id(1L).username("ada").build();
        User b = User.builder().id(1L).username("someone-else").build();
        User c = User.builder().id(2L).username("ada").build();

        assertEquals(a, b);
        assertNotEquals(a, c);
    }
}

